// Input contract: { business_name, whatsapp, sector_code, market_code? }
// The sector must exist in the active catalog and have a pack before tenant creation.
const b = ($json.body ?? $json) || {};
const business_name = String(b.business_name ?? '').trim();
const whatsapp = String(b.whatsapp ?? '').trim();
const sector_code = String(b.sector_code ?? '').trim();
const market_code = String(b.market_code ?? 'EG').trim().toUpperCase();
if (!business_name) throw new Error('activation_rejected: business_name is empty');
if (!whatsapp || whatsapp.replace(/[^0-9+]/g, '').length < 9) throw new Error('activation_rejected: whatsapp is invalid');
if (!/^[a-z][a-z0-9_]*$/.test(sector_code)) throw new Error('activation_rejected: sector_code format is invalid');
if (!['EG', 'SA'].includes(market_code)) throw new Error('activation_rejected: market_code must be EG or SA');
return [{ json: { business_name, whatsapp, sector_code, market_code } }];

// Slug: generated from the BUSINESS NAME, never from the sector name.
// TBD-A2 (do not guess): Arabic-to-Latin transliteration table for Arabic business names.
// Draft rule: keep Latin letters/digits/hyphens only; if nothing remains, fall back to a
// timestamp suffix. Uniqueness is resolved by the next two nodes.
const d = $json;
let slug_candidate = d.business_name.toLowerCase().trim().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
if (!slug_candidate) slug_candidate = 'tenant-' + Date.now().toString(36);
return [{ json: { business_name: d.business_name, whatsapp: d.whatsapp, sector_code: d.sector_code, market_code: d.market_code, slug_candidate } }];

// Slug-only: merges the candidate (from 'Compute Slug Candidate') with the check result ($json).
// If the candidate exists, append '-2' (single retry; repeated collisions are TBD-A1).
// Note: the temp password now comes from Postgres (gen_random_uuid) in the next node; its delivery channel is TBD.
const cand = $('Compute Slug Candidate').first().json;
const slug = $json.slug_exists ? cand.slug_candidate + '-2' : cand.slug_candidate;
return [{ json: { business_name: cand.business_name, whatsapp: cand.whatsapp, sector_code: cand.sector_code, market_code: cand.market_code, slug } }];

// Final output contract — exactly these fields, nothing more.
// owner_login_url uses the staging portal base placeholder; set it at deploy time
// to the real staging portal URL. The temporary password is DELIBERATELY absent.
const t = $('Insert Tenant').first().json;
return [{ json: {
  tenant_id: t.id,
  owner_login_url: 'PUT_OWNER_PORTAL_BASE' + '/owner.html?tenant=' + t.id,
  status: 'trial'
} }];
